#[test]
fn request_template_plan_bodies_match_fabrication_plan_contract() {
    let templates = request_templates();
    let template_entries = templates
        .as_array()
        .expect("request templates should be an array");
    let plan_routes = [
        "POST /fabrication/plan",
        "POST /fabrication/design/generate",
        "POST /fabrication/machine-code/generate",
        "POST /fabrication/instructions/generate",
        "POST /fabrication/simulation/run",
        "POST /fabrication/decomposition/plan",
        "POST /fabrication/assembly/plan",
    ];
    let mut checked = 0;

    for template in template_entries {
        let route = template
            .get("route")
            .and_then(Value::as_str)
            .expect("template should expose route");
        if !plan_routes.contains(&route) {
            continue;
        }
        let request = template
            .get("request")
            .cloned()
            .expect("template should include request body");
        let parsed: FabricationPlanRequest =
            serde_json::from_value(request).expect("template request should match plan schema");
        assert!(
            !parsed.objective.trim().is_empty(),
            "template request objective should be non-empty"
        );
        for part in parsed.parts.unwrap_or_default() {
            assert!(
                !part.description.trim().is_empty(),
                "template request part {} should include description",
                part.id
            );
        }
        checked += 1;
    }

    assert!(
        checked >= 8,
        "expected plan/design/machine-code/simulation starter requests to parse"
    );
}

#[test]
fn request_template_instruction_generation_bodies_match_plan_contract() {
    let templates = request_templates();
    let template_entries = templates
        .as_array()
        .expect("request templates should be an array");
    let mut part_methods = BTreeSet::new();
    let mut checked = 0;

    for template in template_entries {
        let route = template
            .get("route")
            .and_then(Value::as_str)
            .expect("template should expose route");
        if route != "POST /fabrication/instructions/generate" {
            continue;
        }
        let request = template
            .get("request")
            .cloned()
            .expect("instruction generation template should include request body");
        let parsed: FabricationPlanRequest = serde_json::from_value(request)
            .expect("instruction generation template should match plan schema");
        assert!(
            parsed
                .constraints
                .as_ref()
                .and_then(|constraints| constraints.require_dry_run)
                .unwrap_or(false),
            "instruction generation template should require dry run"
        );
        for part in parsed
            .parts
            .expect("instruction generation template should include parts")
        {
            assert!(
                !part.description.trim().is_empty(),
                "instruction generation part {} should include description",
                part.id
            );
            if let Some(method) = part.preferred_method {
                part_methods.insert(method);
            }
        }
        checked += 1;
    }

    assert_eq!(
        checked, 2,
        "expected direct instruction generation templates"
    );
    for expected in ["additive-print", "milling"] {
        assert!(
            part_methods.contains(expected),
            "instruction generation templates should include {expected} part route"
        );
    }
}

#[test]
fn request_template_simulation_run_body_matches_plan_contract() {
    let templates = request_templates();
    let template_entries = templates
        .as_array()
        .expect("request templates should be an array");
    let template = template_entries
        .iter()
        .find(|template| {
            template.get("id").and_then(Value::as_str) == Some("imported-cnc-dry-run-simulation")
        })
        .expect("imported CNC dry-run simulation template should exist");
    assert_eq!(
        template.get("route").and_then(Value::as_str),
        Some("POST /fabrication/simulation/run")
    );
    let request = template
        .get("request")
        .cloned()
        .expect("simulation template should include request body");
    let parsed: FabricationPlanRequest =
        serde_json::from_value(request).expect("simulation template should match plan schema");
    assert!(
        parsed
            .constraints
            .as_ref()
            .and_then(|constraints| constraints.require_dry_run)
            .unwrap_or(false),
        "simulation template should require dry run"
    );
    assert!(
        parsed.machines.as_ref().is_some_and(|machines| machines
            .iter()
            .any(|machine| { machine.kind == "cnc-router" && machine.work_envelope_mm.is_some() })),
        "simulation template should include a machine envelope"
    );
    assert!(
        parsed
            .existing_instructions
            .as_ref()
            .is_some_and(|programs| programs.iter().any(|program| {
                program.language.as_deref() == Some("grbl-gcode")
                    && !program.instructions.is_empty()
            })),
        "simulation template should include imported instructions"
    );
}

#[test]
fn request_template_toolpath_result_body_matches_review_contract() {
    let templates = request_templates();
    let template_entries = templates
        .as_array()
        .expect("request templates should be an array");
    let template = template_entries
        .iter()
        .find(|template| {
            template.get("id").and_then(Value::as_str) == Some("toolpath-result-feedback")
        })
        .expect("toolpath result template should exist");
    assert_eq!(
        template.get("route").and_then(Value::as_str),
        Some("POST /fabrication/toolpaths/result")
    );
    let request = template
        .get("request")
        .cloned()
        .expect("toolpath result template should include request body");
    let parsed: ToolpathResultReviewRequest = serde_json::from_value(request)
        .expect("toolpath result template should match review schema");
    assert_eq!(parsed.worker_id, "toolpath-simulation-worker");
    assert!(!parsed.machine_ready);
    assert!(
        parsed
            .toolpaths
            .as_ref()
            .is_some_and(|segments| segments.iter().any(|segment| {
                segment.machine_ready == Some(false)
                    && segment.requires_human_intervention == Some(true)
            })),
        "toolpath result template should retain blocking toolpath segments"
    );
    assert!(
        parsed
            .simulations
            .as_ref()
            .is_some_and(|simulations| simulations.iter().any(|simulation| {
                simulation.collision_free == Some(false)
                    && simulation.clearance_ok == Some(false)
                    && simulation.dry_run_passed == Some(false)
            })),
        "toolpath result template should retain collision, clearance, and dry-run blockers"
    );
    assert!(
        parsed
            .checks
            .as_ref()
            .is_some_and(|checks| checks.iter().any(|check| {
                check.release_blocker == Some(true)
                    && check.requires_human_intervention == Some(true)
            })),
        "toolpath result template should retain release-blocking checks"
    );
    let payload =
        toolpath_result_review_response(parsed).expect("toolpath result template should normalize");
    assert_eq!(
        payload.get("machineReady").and_then(Value::as_bool),
        Some(false)
    );
    assert_eq!(
        payload.get("schemaVersion").and_then(Value::as_str),
        Some("dd.fabrication.toolpath-result-review.v1")
    );
}

