#[test]
fn mesh_repair_result_endpoint_reviews_topology_drift_split_and_learning() {
    let response = mesh_repair_result_review_response(MeshRepairResultReviewRequest {
        request_id: Some("mesh-repair-result-001".to_string()),
        plan_request_id: Some("plan-mesh-repair-001".to_string()),
        job_id: Some("job-mesh-repair-001".to_string()),
        worker_id: "mesh-repair-worker".to_string(),
        reviewer: Some("geometry-repair-reviewer".to_string()),
        reviewer_version: Some("2026.06-mesh".to_string()),
        source_design_id: Some("scan-bust-001".to_string()),
        source_format: Some("ply-color-scan-mesh".to_string()),
        target_format: Some("3mf".to_string()),
        success: true,
        machine_ready: false,
        slicer_ready: Some(false),
        topology_checks: Some(vec![MeshRepairResultCheck {
            check_id: "topology-check-001".to_string(),
            repair_domain: "watertight-topology".to_string(),
            check_kind: "nonmanifold-edge-repair".to_string(),
            status: "split-combine-review-required".to_string(),
            passed: Some(false),
            release_blocker: Some(true),
            requires_human_intervention: Some(true),
            requires_split_combine: Some(true),
            evidence: Some(vec![
                "scan shell repaired except undercut region that needs split review".to_string(),
                "operator must approve topology change before slicer handoff".to_string(),
            ]),
        }]),
        dimensional_reviews: Some(vec![MeshRepairDimensionalReview {
            review_id: "dimension-review-001".to_string(),
            feature_id: Some("mounting-boss".to_string()),
            status: "dimension-drift-over-tolerance".to_string(),
            max_drift_mm: Some(0.42),
            tolerance_mm: Some(0.20),
            wall_thickness_mm: Some(0.85),
            release_blocker: Some(true),
            requires_redesign: Some(true),
            requires_split_combine: Some(true),
            evidence: Some(vec![
                "repair drift exceeds tolerance at mounting boss".to_string()
            ]),
        }]),
        orientation_reviews: Some(vec![MeshRepairResultCheck {
            check_id: "orientation-review-001".to_string(),
            repair_domain: "orientation-support-and-slice-readiness".to_string(),
            check_kind: "support-contact-preview".to_string(),
            status: "first-layer-review-required".to_string(),
            passed: Some(false),
            release_blocker: Some(true),
            requires_human_intervention: Some(true),
            requires_split_combine: Some(false),
            evidence: Some(vec![
                "support scars would cross visible color texture region".to_string(),
            ]),
        }]),
        artifacts: Some(vec![MeshRepairResultArtifact {
            artifact_id: "mesh-repair-report-001".to_string(),
            artifact_kind: "mesh-repair-report".to_string(),
            source_ref_id: Some("topology-check-001".to_string()),
            uri: Some("s3://fabrication/mesh-repair-report-001.json".to_string()),
            sha256: Some("e".repeat(64)),
            format: Some("json".to_string()),
            evidence: Some(vec![
                "retained topology, drift, orientation, and split review evidence".to_string(),
            ]),
        }]),
        warnings: Some(vec![
            "slicer release remains blocked until split and drift review clear".to_string(),
        ]),
        review_metadata: Some(json!({"source": "unit-test"})),
    })
    .expect("mesh repair result should be accepted");

    assert_eq!(
        response.get("schemaVersion").and_then(Value::as_str),
        Some("dd.fabrication.mesh-repair-result-review.v1")
    );
    assert!(response
        .get("routes")
        .and_then(Value::as_array)
        .is_some_and(|routes| routes
            .iter()
            .any(|route| route.as_str() == Some("POST /fabrication/mesh-repair/result"))));
    assert_eq!(
        response.get("reviewStatus").and_then(Value::as_str),
        Some("mesh-repair-result-topology-release-blocked")
    );
    assert_eq!(
        response.get("releaseBlocked").and_then(Value::as_bool),
        Some(true)
    );
    assert_eq!(
        response.get("topologyBlockerCount").and_then(Value::as_u64),
        Some(1)
    );
    assert_eq!(
        response
            .get("dimensionalBlockerCount")
            .and_then(Value::as_u64),
        Some(1)
    );
    assert_eq!(
        response
            .get("orientationBlockerCount")
            .and_then(Value::as_u64),
        Some(1)
    );
    assert_eq!(
        response
            .get("splitCombineRequired")
            .and_then(Value::as_bool),
        Some(true)
    );
    assert_eq!(
        response.get("redesignRequired").and_then(Value::as_bool),
        Some(true)
    );
    assert_eq!(
        response.get("driftOverTolerance").and_then(Value::as_bool),
        Some(true)
    );

    let observations = response
        .get("learning")
        .and_then(|learning| learning.get("observations"))
        .and_then(Value::as_array)
        .expect("learning observations should be retained");
    for observation in [
        "mesh-repair:release-blocked",
        "mesh-repair:human-intervention-required",
        "mesh-repair:split-combine-required",
        "mesh-repair:redesign-required",
        "mesh-repair:dimension-drift-over-tolerance",
        "mesh-repair-domain:watertight-topology",
        "mesh-repair-check:nonmanifold-edge-repair",
        "mesh-repair-orientation:support-contact-preview",
    ] {
        assert!(
            observations
                .iter()
                .any(|item| item.as_str() == Some(observation)),
            "missing learning observation {observation}"
        );
    }
    let outcome_draft = response
        .pointer("/learning/outcomeDraft")
        .expect("mesh repair learning outcome draft should be retained");
    assert_eq!(
        outcome_draft.get("schemaVersion").and_then(Value::as_str),
        Some("dd.fabrication.mesh-repair-learning-outcome-draft.v1")
    );
    assert_eq!(
        outcome_draft
            .get("recommendedSubmitRoute")
            .and_then(Value::as_str),
        Some("POST /fabrication/learning/outcomes")
    );
    assert_eq!(
        outcome_draft.get("success").and_then(Value::as_bool),
        Some(false)
    );
    assert_eq!(
        outcome_draft.get("rewardHint").and_then(Value::as_f64),
        Some(-0.62)
    );
    assert!(outcome_draft
        .get("topologyHints")
        .and_then(Value::as_array)
        .is_some_and(|hints| hints.iter().any(|hint| {
            hint.get("checkKind").and_then(Value::as_str) == Some("nonmanifold-edge-repair")
                && hint.get("requiresSplitCombine").and_then(Value::as_bool) == Some(true)
        })));
    assert!(outcome_draft
        .get("dimensionalHints")
        .and_then(Value::as_array)
        .is_some_and(|hints| hints.iter().any(|hint| {
            hint.get("featureId").and_then(Value::as_str) == Some("mounting-boss")
                && hint.get("requiresRedesign").and_then(Value::as_bool) == Some(true)
        })));
    assert!(outcome_draft
        .get("orientationHints")
        .and_then(Value::as_array)
        .is_some_and(|hints| hints.iter().any(|hint| {
            hint.get("checkKind").and_then(Value::as_str) == Some("support-contact-preview")
                && hint
                    .get("requiresHumanIntervention")
                    .and_then(Value::as_bool)
                    == Some(true)
        })));
    assert_eq!(
        outcome_draft
            .pointer("/featureHints/splitCombineRequired")
            .and_then(Value::as_bool),
        Some(true)
    );
    assert_eq!(
        outcome_draft
            .pointer("/featureHints/driftOverTolerance")
            .and_then(Value::as_bool),
        Some(true)
    );

    let job = stored_mesh_repair_result_job(&response);
    assert_eq!(job.record.kind, "mesh-repair-result");
    assert_eq!(
        job.record.status,
        "mesh-repair-result-topology-release-blocked"
    );
    assert_eq!(job.record.severity, "error");
    for artifact_id in [
        "mesh-repair-result",
        "mesh-repair-topology-checks",
        "mesh-repair-dimensional-reviews",
        "mesh-repair-orientation-reviews",
        "mesh-repair-artifacts",
        "mesh-repair-learning-observations",
    ] {
        assert!(
            job.artifacts.contains_key(artifact_id),
            "missing retained artifact {artifact_id}"
        );
    }
}

#[test]
fn design_import_catalog_endpoint_exposes_native_cad_worker_lanes() {
    let payload = design_import_catalog_response();
    assert_eq!(
        payload.get("schemaVersion").and_then(Value::as_str),
        Some("dd.fabrication.design-import-catalog.v1")
    );
    assert_eq!(
        payload.get("formatContractCount").and_then(Value::as_u64),
        Some(DESIGN_FORMAT_SPECS.len() as u64)
    );
    assert!(payload
        .get("routes")
        .and_then(Value::as_array)
        .is_some_and(|routes| routes
            .iter()
            .any(|route| { route.as_str() == Some("GET /fabrication/formats/catalog") })));
    assert!(payload
        .get("routes")
        .and_then(Value::as_array)
        .is_some_and(|routes| routes
            .iter()
            .any(|route| { route.as_str() == Some("GET /fabrication/design/import/catalog") })));
    assert_eq!(
        payload
            .get("conversionSubjects")
            .and_then(|subjects| subjects.get("requests"))
            .and_then(Value::as_str),
        Some(FABRICATION_DESIGN_CONVERSION_REQUESTS_SUBJECT)
    );
    assert_eq!(
        payload
            .get("conversionSubjects")
            .and_then(|subjects| subjects.get("queueGroup"))
            .and_then(Value::as_str),
        Some("dd-fabrication-design-conversion")
    );

    let source_systems = payload
        .get("sourceSystems")
        .and_then(Value::as_array)
        .expect("source systems should be present");
    for system in [
        "PTC Creo / Pro/ENGINEER",
        "SOLIDWORKS",
        "Autodesk Fusion",
        "Siemens NX",
        "CATIA",
        "Onshape",
        "FreeCAD",
        "OpenSCAD",
        "Blender",
        "ZBrush",
        "JT",
    ] {
        assert!(
            source_systems
                .iter()
                .any(|source_system| source_system.as_str() == Some(system)),
            "missing import source system {system}"
        );
    }

    let worker_lanes = payload
        .get("workerLanes")
        .and_then(Value::as_array)
        .expect("worker lanes should be present");
    for lane in [
        "professional-cad-converter",
        "parametric-cad-converter",
        "lightweight-cad-pmi-inspector",
        "cad-kernel-inspector",
        "slicer-profile-reviewer",
    ] {
        assert!(
            worker_lanes.iter().any(|item| item.as_str() == Some(lane)),
            "missing design import worker lane {lane}"
        );
    }

    let contracts = payload
        .get("formatContracts")
        .and_then(Value::as_array)
        .expect("format contracts should be present");
    let solidworks = contracts
        .iter()
        .find(|item| {
            item.get("normalizedFormat").and_then(Value::as_str) == Some("solidworks-native")
        })
        .expect("SOLIDWORKS import contract should be present");
    assert_eq!(
        solidworks.get("workerLane").and_then(Value::as_str),
        Some("professional-cad-converter")
    );
    assert!(solidworks
        .get("releaseBlockers")
        .and_then(Value::as_array)
        .is_some_and(|blockers| blockers.iter().any(|blocker| blocker
            .as_str()
            .is_some_and(|blocker| blocker.contains("native-cad-translator")))));

    let jt = contracts
        .iter()
        .find(|item| {
            item.get("normalizedFormat").and_then(Value::as_str) == Some("jt-lightweight-cad")
        })
        .expect("JT import contract should be present");
    assert_eq!(
        jt.get("workerLane").and_then(Value::as_str),
        Some("lightweight-cad-pmi-inspector")
    );
    assert!(jt
        .get("requiredEvidence")
        .and_then(Value::as_array)
        .is_some_and(|evidence| evidence
            .iter()
            .any(|item| item.as_str().is_some_and(|item| item.contains("PMI")))));
    assert!(payload
        .get("ambiguityPolicy")
        .and_then(Value::as_array)
        .is_some_and(|policy| policy
            .iter()
            .any(|item| item.as_str().is_some_and(|item| item.contains(".prt")))));
    let readiness = payload
        .get("translatorReadinessChecklist")
        .and_then(Value::as_array)
        .expect("translator readiness checklist should be present");
    for check_id in [
        "native-cad-translator-provenance",
        "neutral-kernel-and-pmi-preservation",
        "mesh-slicer-profile-readiness",
        "sheet-profile-and-cam-handoff",
    ] {
        assert!(
            readiness
                .iter()
                .any(|item| item.get("checkId").and_then(Value::as_str) == Some(check_id)),
            "missing translator readiness check {check_id}"
        );
    }
    assert!(readiness.iter().any(|item| item
        .get("requiredEvidence")
        .and_then(Value::as_array)
        .is_some_and(|evidence| evidence.iter().any(|entry| entry
            .as_str()
            .is_some_and(|entry| entry.contains("translator or export worker identity"))))));
    assert!(readiness.iter().any(
        |item| item
            .get("blocks")
            .and_then(Value::as_array)
            .is_some_and(|blocks| blocks
                .iter()
                .any(|entry| entry.as_str() == Some("machine-code-generation")))
    ));
    assert!(readiness.iter().any(|item| item
        .get("learningSignals")
        .and_then(Value::as_array)
        .is_some_and(|signals| signals.iter().any(|entry| entry
            .as_str()
            .is_some_and(|entry| entry.contains("cad-translator"))))));
    assert!(payload
        .get("releasePolicy")
        .and_then(Value::as_array)
        .is_some_and(|policy| policy.iter().any(|item| item
            .as_str()
            .is_some_and(|item| item.contains("machine-ready release remains blocked")))));
}

