#[test]
fn design_conversion_result_endpoint_reviews_exports_blockers_and_learning() {
    let payload = design_conversion_result_review_response(DesignConversionResultReviewRequest {
        request_id: Some("unit-design-conversion-result".to_string()),
        source_job_id: Some("design-job-123".to_string()),
        input_id: Some("solidworks-part".to_string()),
        source_format: Some("SLDPRT".to_string()),
        source_system: Some("SOLIDWORKS".to_string()),
        worker_lane: Some("professional-cad-converter".to_string()),
        status: Some("converted".to_string()),
        converted: Some(true),
        neutral_exports: Some(vec![DesignConversionNeutralExport {
            format: "STEP".to_string(),
            uri: Some("s3://fabrication/design-job-123/solidworks-part.step".to_string()),
            checksum: Some("sha256:abc123".to_string()),
            media_type: Some("model/step".to_string()),
            role: Some("neutral-cad".to_string()),
            units: Some("mm".to_string()),
        }]),
        evidence: Some(vec![
            "translator version captured".to_string(),
            "topology check passed".to_string(),
        ]),
        blockers: None,
        notes: Some(vec!["ready for downstream CAD/CAM review".to_string()]),
        metadata: None,
    })
    .expect("conversion result review should be generated");

    assert_eq!(
        payload.get("schemaVersion").and_then(Value::as_str),
        Some("dd.fabrication.design-conversion-result-review.v1")
    );
    assert!(payload
        .get("routes")
        .and_then(Value::as_array)
        .is_some_and(|routes| routes
            .iter()
            .any(|route| { route.as_str() == Some("POST /fabrication/design/convert/result") })));
    assert_eq!(
        payload.get("reviewStatus").and_then(Value::as_str),
        Some("conversion-result-ready-for-review")
    );
    assert_eq!(
        payload.get("releaseBlocked").and_then(Value::as_bool),
        Some(false)
    );
    let priority_dispositions = payload
        .get("priorityDispositions")
        .and_then(Value::as_array)
        .expect("design conversion priority dispositions");
    assert!(priority_dispositions.iter().any(|disposition| {
        disposition.get("priorityId").and_then(Value::as_str)
            == Some("conversion-success-readiness")
            && disposition.get("disposition").and_then(Value::as_str) == Some("closed")
    }));
    assert!(priority_dispositions.iter().any(|disposition| {
        disposition.get("priorityId").and_then(Value::as_str)
            == Some("learning-feedback-after-disposition")
            && disposition.get("disposition").and_then(Value::as_str) == Some("ready-for-learning")
    }));
    assert_eq!(
        payload.get("resultSubject").and_then(Value::as_str),
        Some(FABRICATION_DESIGN_CONVERSION_RESULTS_SUBJECT)
    );
    assert!(payload
        .get("learning")
        .and_then(|learning| learning.get("observations"))
        .and_then(Value::as_array)
        .is_some_and(|observations| observations
            .iter()
            .any(|observation| { observation.as_str() == Some("design-conversion:converted") })));
    let outcome_draft = payload
        .get("learning")
        .and_then(|learning| learning.get("outcomeDraft"))
        .expect("design conversion learning outcome draft");
    assert_eq!(
        outcome_draft.get("schemaVersion").and_then(Value::as_str),
        Some("dd.fabrication.design-conversion-learning-outcome-draft.v1")
    );
    assert_eq!(
        outcome_draft
            .get("recommendedSubmitRoute")
            .and_then(Value::as_str),
        Some("POST /fabrication/learning/outcomes")
    );
    assert_eq!(
        outcome_draft.get("success").and_then(Value::as_bool),
        Some(true)
    );
    assert_eq!(
        outcome_draft.get("rewardHint").and_then(Value::as_f64),
        Some(0.48)
    );
    assert!(outcome_draft
        .get("neutralExportFormats")
        .and_then(Value::as_array)
        .is_some_and(|formats| formats.iter().any(|format| format.as_str() == Some("STEP"))));
    assert!(outcome_draft
        .get("priorityDispositions")
        .and_then(Value::as_array)
        .is_some_and(|dispositions| dispositions.iter().any(|disposition| {
            disposition
                .get("learningObservation")
                .and_then(Value::as_str)
                .is_some_and(|observation| {
                    observation.contains(
                        "design-conversion-priority:neutral-export-evidence-retention:closed",
                    )
                })
        })));
    assert_eq!(
        outcome_draft
            .get("featureHints")
            .and_then(|features| features.get("missingReleaseEvidence"))
            .and_then(Value::as_bool),
        Some(false)
    );

    let blocked = design_conversion_result_review_response(DesignConversionResultReviewRequest {
        request_id: Some("unit-design-conversion-blocked".to_string()),
        source_job_id: Some("design-job-456".to_string()),
        input_id: Some("ambiguous-prt".to_string()),
        source_format: Some("PRT".to_string()),
        source_system: None,
        worker_lane: Some("professional-cad-converter".to_string()),
        status: Some("blocked missing source system".to_string()),
        converted: Some(false),
        neutral_exports: None,
        evidence: None,
        blockers: Some(vec!["source system is ambiguous".to_string()]),
        notes: None,
        metadata: None,
    })
    .expect("blocked conversion result review should be generated");
    assert_eq!(
        blocked.get("releaseBlocked").and_then(Value::as_bool),
        Some(true)
    );
    assert!(blocked
        .get("learning")
        .and_then(|learning| learning.get("observations"))
        .and_then(Value::as_array)
        .is_some_and(
            |observations| observations.iter().any(|observation| observation
                .as_str()
                .is_some_and(|observation| observation.contains("release-blocked")))
        ));
    assert!(blocked
        .get("priorityDispositions")
        .and_then(Value::as_array)
        .is_some_and(|dispositions| dispositions.iter().any(|disposition| {
            disposition.get("priorityId").and_then(Value::as_str) == Some("blocker-review-closure")
                && disposition.get("disposition").and_then(Value::as_str) == Some("blocked")
        })));
    let blocked_outcome_draft = blocked
        .get("learning")
        .and_then(|learning| learning.get("outcomeDraft"))
        .expect("blocked design conversion learning outcome draft");
    assert_eq!(
        blocked_outcome_draft
            .get("success")
            .and_then(Value::as_bool),
        Some(false)
    );
    assert_eq!(
        blocked_outcome_draft
            .get("rewardHint")
            .and_then(Value::as_f64),
        Some(-0.58)
    );
    assert!(blocked_outcome_draft
        .get("blockerHints")
        .and_then(Value::as_array)
        .is_some_and(|blockers| blockers
            .iter()
            .any(|blocker| blocker.as_str() == Some("source system is ambiguous"))));
}

#[test]
fn design_synthesis_result_endpoint_reviews_candidates_and_learning() {
    let payload = design_synthesis_result_review_response(DesignSynthesisResultReviewRequest {
        request_id: Some("unit-design-synthesis-result".to_string()),
        source_job_id: Some("design-job-789".to_string()),
        worker_lane: Some("parametric-design-synthesizer".to_string()),
        status: Some("generated candidates".to_string()),
        accepted_candidate_id: Some("candidate-bracket".to_string()),
        candidates: Some(vec![DesignSynthesisCandidateResult {
            candidate_id: "candidate-bracket".to_string(),
            part_ids: Some(vec!["bracket-body".to_string(), "turned-pin".to_string()]),
            representation: Some("parametric assembly graph".to_string()),
            source_artifact_uri: Some(
                "s3://fabrication/design-job-789/candidate-bracket.json".to_string(),
            ),
            export_formats: Some(vec!["STEP".to_string(), "3MF".to_string()]),
            manufacturing_methods: Some(vec![
                "milling".to_string(),
                "turning".to_string(),
                "additive-print".to_string(),
            ]),
            review_status: Some("review-required".to_string()),
        }]),
        manufacturability_evidence: Some(vec![
            "fits selected mill and lathe envelopes".to_string(),
            "split printed gauge from metal bracket".to_string(),
        ]),
        blockers: None,
        notes: Some(vec!["ready for CAD/CAM export review".to_string()]),
        metadata: None,
    })
    .expect("design synthesis result review should be generated");

    assert_eq!(
        payload.get("schemaVersion").and_then(Value::as_str),
        Some("dd.fabrication.design-synthesis-result-review.v1")
    );
    assert!(payload
        .get("routes")
        .and_then(Value::as_array)
        .is_some_and(|routes| routes
            .iter()
            .any(|route| { route.as_str() == Some("POST /fabrication/design/synthesis/result") })));
    assert_eq!(
        payload.get("reviewStatus").and_then(Value::as_str),
        Some("design-synthesis-result-ready-for-review")
    );
    assert_eq!(
        payload.get("releaseBlocked").and_then(Value::as_bool),
        Some(false)
    );
    assert_eq!(
        payload.get("machineReady").and_then(Value::as_bool),
        Some(false)
    );
    assert_eq!(
        payload.get("resultSubject").and_then(Value::as_str),
        Some(FABRICATION_DESIGN_SYNTHESIS_RESULTS_SUBJECT)
    );
    assert!(payload
        .get("designSynthesisResult")
        .and_then(|result| result.get("candidates"))
        .and_then(Value::as_array)
        .is_some_and(|candidates| candidates.iter().any(|candidate| candidate
            .get("candidateId")
            .and_then(Value::as_str)
            == Some("candidate-bracket"))));
    assert!(payload
        .get("learning")
        .and_then(|learning| learning.get("observations"))
        .and_then(Value::as_array)
        .is_some_and(|observations| observations.iter().any(|observation| {
            observation.as_str() == Some("design-synthesis-worker:parametric-design-synthesizer")
        })));
    let observations = payload
        .get("learning")
        .and_then(|learning| learning.get("observations"))
        .and_then(Value::as_array)
        .expect("design synthesis learning observations should be retained");
    for expected in [
        "design-synthesis-priority:candidate-selection-readiness:closed",
        "design-synthesis-priority:blocker-review-closure:closed",
        "design-synthesis-priority:release-evidence-retention:closed",
        "design-synthesis-priority:manufacturability-evidence:closed",
        "design-synthesis-priority:learning-feedback-after-disposition:ready-for-learning",
    ] {
        assert!(
            observations
                .iter()
                .any(|observation| observation.as_str() == Some(expected)),
            "missing design synthesis learning observation {expected}"
        );
    }
    let priority_dispositions = payload
        .get("priorityDispositions")
        .and_then(Value::as_array)
        .expect("design synthesis priority dispositions should be retained");
    for expected in [
        (
            "candidate-selection-readiness",
            "closed",
            "design-synthesis-priority:candidate-selection-readiness:closed",
        ),
        (
            "blocker-review-closure",
            "closed",
            "design-synthesis-priority:blocker-review-closure:closed",
        ),
        (
            "release-evidence-retention",
            "closed",
            "design-synthesis-priority:release-evidence-retention:closed",
        ),
        (
            "manufacturability-evidence",
            "closed",
            "design-synthesis-priority:manufacturability-evidence:closed",
        ),
        (
            "learning-feedback-after-disposition",
            "ready-for-learning",
            "design-synthesis-priority:learning-feedback-after-disposition:ready-for-learning",
        ),
    ] {
        assert!(
            priority_dispositions.iter().any(|disposition| {
                disposition.get("priorityId").and_then(Value::as_str) == Some(expected.0)
                    && disposition.get("disposition").and_then(Value::as_str) == Some(expected.1)
                    && disposition
                        .get("learningObservation")
                        .and_then(Value::as_str)
                        == Some(expected.2)
            }),
            "missing design synthesis priority disposition {}",
            expected.0
        );
    }
    let outcome_draft = payload
        .get("learning")
        .and_then(|learning| learning.get("outcomeDraft"))
        .expect("design synthesis learning outcome draft");
    assert_eq!(
        outcome_draft.get("schemaVersion").and_then(Value::as_str),
        Some("dd.fabrication.design-synthesis-learning-outcome-draft.v1")
    );
    assert_eq!(
        outcome_draft
            .get("recommendedSubmitRoute")
            .and_then(Value::as_str),
        Some("POST /fabrication/learning/outcomes")
    );
    assert_eq!(
        outcome_draft.get("success").and_then(Value::as_bool),
        Some(true)
    );
    assert_eq!(
        outcome_draft
            .get("acceptedCandidateId")
            .and_then(Value::as_str),
        Some("candidate-bracket")
    );
    assert!(outcome_draft
        .get("partHints")
        .and_then(Value::as_array)
        .is_some_and(|parts| parts.iter().any(|part| part.as_str() == Some("turned-pin"))));
    assert!(outcome_draft
        .get("manufacturingMethodHints")
        .and_then(Value::as_array)
        .is_some_and(|methods| methods
            .iter()
            .any(|method| method.as_str() == Some("additive-print"))));
    assert_eq!(
        outcome_draft
            .get("featureHints")
            .and_then(|features| features.get("acceptedCandidateSelected"))
            .and_then(Value::as_bool),
        Some(true)
    );
    assert!(outcome_draft
        .get("priorityDispositions")
        .and_then(Value::as_array)
        .is_some_and(|dispositions| dispositions.iter().any(|disposition| {
            disposition.get("priorityId").and_then(Value::as_str)
                == Some("candidate-selection-readiness")
        })));
}

