#[test]
fn machine_code_catalog_endpoint_exposes_program_controller_and_learning_contract() {
    let payload = machine_code_catalog_response();
    assert_eq!(
        payload.get("schemaVersion").and_then(Value::as_str),
        Some("dd.fabrication.machine-code-catalog.v1")
    );
    assert!(payload
        .get("routes")
        .and_then(Value::as_array)
        .is_some_and(|routes| routes
            .iter()
            .any(|route| route.as_str() == Some("GET /fabrication/machine-code/catalog"))));
    assert!(payload
        .get("generationRoutes")
        .and_then(Value::as_array)
        .is_some_and(|routes| routes
            .iter()
            .any(|route| route.as_str() == Some("POST /fabrication/machine-code/generate"))));
    assert!(payload
        .get("programContractCount")
        .and_then(Value::as_u64)
        .is_some_and(|count| count >= 8));
    assert_eq!(
        payload.get("controllerTargetCount").and_then(Value::as_u64),
        Some(default_machines().len() as u64)
    );
    assert!(payload
        .get("generatedLanguages")
        .and_then(Value::as_array)
        .is_some_and(|languages| languages
            .iter()
            .any(|language| language.as_str() == Some("haas-gcode"))));
    assert!(payload
        .get("generatedLanguages")
        .and_then(Value::as_array)
        .is_some_and(|languages| languages
            .iter()
            .any(|language| language.as_str() == Some("ctb-resin-job"))));
    assert!(payload
        .get("machineClasses")
        .and_then(Value::as_array)
        .is_some_and(|classes| classes
            .iter()
            .any(|class| class.as_str() == Some("vertical-mill"))));
    assert!(payload
        .get("dialectFamilies")
        .and_then(Value::as_array)
        .is_some_and(|dialects| dialects
            .iter()
            .any(|dialect| dialect.as_str() == Some("subtractive-gcode-controller-dialect"))));
    assert!(payload
        .get("postprocessors")
        .and_then(Value::as_array)
        .is_some_and(|postprocessors| postprocessors.iter().any(|postprocessor| {
            postprocessor.as_str() == Some("haas-mill-gcode-postprocessor")
        })));
    assert!(payload
        .get("responseSurfaces")
        .and_then(Value::as_array)
        .is_some_and(|surfaces| surfaces
            .iter()
            .any(|surface| surface.as_str() == Some("controllerPlan.releaseGates"))));
    assert!(payload
        .get("releaseEvidence")
        .and_then(Value::as_array)
        .is_some_and(|evidence| evidence.iter().any(|item| item
            .as_str()
            .is_some_and(|item| item.contains("simulation, dry-run")))));
    assert!(payload
        .get("learningSurfaces")
        .and_then(Value::as_array)
        .is_some_and(|surfaces| surfaces
            .iter()
            .any(|surface| surface.as_str() == Some("neuralTrainingCorpus.examples"))));
    assert!(payload
        .get("machineCodePolicy")
        .and_then(Value::as_array)
        .is_some_and(|policy| policy.iter().any(|item| item
            .as_str()
            .is_some_and(|item| item.contains("draft=true")))));
    let target_matrix = payload
        .get("targetSelectionMatrix")
        .and_then(Value::as_array)
        .expect("machine-code target selection matrix should be present");
    for family in [
        "additive-printer-firmware",
        "subtractive-mill-router-controller",
        "turning-and-mill-turn-controller",
        "sheet-cutting-edm-and-special-process",
        "hybrid-assembly-and-human-reviewed-instructions",
    ] {
        assert!(
            target_matrix
                .iter()
                .any(|entry| { entry.get("targetFamily").and_then(Value::as_str) == Some(family) }),
            "missing machine-code target family {family}"
        );
    }
    assert!(target_matrix.iter().any(|entry| entry
        .get("machineKinds")
        .and_then(Value::as_array)
        .is_some_and(|kinds| kinds
            .iter()
            .any(|kind| kind.as_str() == Some("horizontal-mill")))));
    assert!(target_matrix.iter().any(|entry| entry
        .get("releaseEvidence")
        .and_then(Value::as_array)
        .is_some_and(|evidence| evidence.iter().any(|item| {
            item.as_str()
                .is_some_and(|item| item.contains("part-off support"))
        }))));
    assert!(target_matrix.iter().any(|entry| entry
        .get("fallback")
        .and_then(Value::as_str)
        .is_some_and(|fallback| fallback.contains("machineReady=false"))));
}

#[test]
fn machine_code_preflight_catalog_endpoint_exposes_controller_release_gates() {
    let payload = machine_code_preflight_catalog_response();
    assert_eq!(
        payload.get("schemaVersion").and_then(Value::as_str),
        Some("dd.fabrication.machine-code-preflight-catalog.v1")
    );
    assert!(payload
        .get("routes")
        .and_then(Value::as_array)
        .is_some_and(|routes| routes.iter().any(|route| {
            route.as_str() == Some("GET /fabrication/machine-code/preflight/catalog")
        })));
    assert!(payload
        .get("generatedLanguages")
        .and_then(Value::as_array)
        .is_some_and(|languages| languages
            .iter()
            .any(|language| language.as_str() == Some("haas-gcode"))));
    assert!(payload
        .get("machineClasses")
        .and_then(Value::as_array)
        .is_some_and(|classes| classes
            .iter()
            .any(|class| class.as_str() == Some("vertical-mill"))));

    let groups = payload
        .get("preflightGroups")
        .and_then(Value::as_array)
        .expect("machine-code preflight groups should be exposed");
    for group in [
        "program-source-and-design-state",
        "controller-postprocessor-and-dialect-state",
        "machine-setup-toolpath-and-process-state",
        "validation-simulation-release-and-learning-state",
    ] {
        assert!(
            groups
                .iter()
                .any(|item| item.get("group").and_then(Value::as_str) == Some(group)),
            "missing machine-code preflight group {group}"
        );
    }
    assert!(payload
        .get("responseSurfaces")
        .and_then(Value::as_array)
        .is_some_and(|surfaces| surfaces
            .iter()
            .any(|surface| surface.as_str() == Some("controllerPlan.releaseGates"))));
    assert!(payload
        .get("artifactSurfaces")
        .and_then(Value::as_array)
        .is_some_and(|surfaces| surfaces
            .iter()
            .any(|surface| surface.as_str() == Some("generated-machine-program"))));
    assert!(payload
        .get("releasePolicy")
        .and_then(Value::as_array)
        .is_some_and(|policy| policy.iter().any(|item| item
            .as_str()
            .is_some_and(|item| item.contains("machineReady=false")))));
}

#[test]
fn machine_code_generation_endpoint_returns_controller_release_package() {
    let policy = LearningPolicySnapshot {
        outcome_count: 0,
        successes: 0,
        failures: 0,
        average_reward: 0.0,
        method_preferences: Vec::new(),
        method_combination_preferences: Vec::new(),
        machine_kind_preferences: Vec::new(),
        operation_sequence_preferences: Vec::new(),
        assembly_preferences: Vec::new(),
        split_combine_preferences: Vec::new(),
        remediation_risks: Vec::new(),
        neural_training_examples: Vec::new(),
        boundary_learning_examples: Vec::new(),
    };
    let response = plan_fabrication_with_policy(
        FabricationPlanRequest {
            request_id: Some("unit-machine-code-generate".to_string()),
            objective: "aluminum bracket with milled datum pocket and turned steel pin".to_string(),
            material: Some(material("aluminum", "metal")),
            stock: None,
            tolerance_mm: Some(0.05),
            quantity: Some(1),
            machines: None,
            constraints: None,
            parts: None,
            design_inputs: None,
            existing_instructions: None,
            learning: None,
        },
        Some(&policy),
    )
    .expect("machine-code generation plan should succeed");

    let payload = machine_code_generation_response(&response, &policy);
    assert_eq!(
        payload.get("schemaVersion").and_then(Value::as_str),
        Some("dd.fabrication.machine-code-generation.v1")
    );
    assert!(payload
        .get("routes")
        .and_then(Value::as_array)
        .is_some_and(|routes| routes
            .iter()
            .any(|route| { route.as_str() == Some("POST /fabrication/machine-code/generate") })));
    assert!(payload
        .get("machineCodeProgramCount")
        .and_then(Value::as_u64)
        .is_some_and(|count| count > 0));
    assert!(payload
        .get("programLanguages")
        .and_then(Value::as_array)
        .is_some_and(|languages| !languages.is_empty()));
    assert!(payload
        .get("controllerRelease")
        .and_then(|release| release.get("targetCount"))
        .and_then(Value::as_u64)
        .is_some_and(|count| count > 0));
    assert!(payload
        .get("controllerPlan")
        .and_then(|plan| plan.get("compatibilityTargets"))
        .and_then(Value::as_array)
        .is_some_and(|targets| !targets.is_empty()));
    assert!(payload
        .get("responseSurfaces")
        .and_then(Value::as_array)
        .is_some_and(|surfaces| surfaces
            .iter()
            .any(|surface| { surface.as_str() == Some("controllerPlan.releaseGates") })));
    assert_eq!(
        payload.get("machineReady").and_then(Value::as_bool),
        Some(false)
    );
    assert!(
        payload
            .get("learning")
            .and_then(|learning| learning.get("engine"))
            .and_then(|engine| engine.get("crateName"))
            .and_then(Value::as_str)
            == Some("des_engine")
    );

    let job = stored_plan_job(&response);
    assert!(job
        .artifacts
        .values()
        .any(|artifact| artifact.kind == "generated-machine-program"));
    assert!(job.artifacts.contains_key("controller-plan"));
    assert!(job.artifacts.contains_key("release-package-plan"));
}

#[test]
fn slicer_profile_planning_endpoint_returns_profile_machine_code_and_release_contract() {
    let policy = LearningPolicySnapshot {
        outcome_count: 0,
        successes: 0,
        failures: 0,
        average_reward: 0.0,
        method_preferences: Vec::new(),
        method_combination_preferences: Vec::new(),
        machine_kind_preferences: Vec::new(),
        operation_sequence_preferences: Vec::new(),
        assembly_preferences: Vec::new(),
        split_combine_preferences: Vec::new(),
        remediation_risks: Vec::new(),
        neural_training_examples: Vec::new(),
        boundary_learning_examples: Vec::new(),
    };
    let response = plan_fabrication_with_policy(
        FabricationPlanRequest {
            request_id: Some("unit-slicer-profile-plan".to_string()),
            objective: "print a PETG-CF electronics bracket with support-critical overhangs"
                .to_string(),
            material: Some(material("PETG-CF", "polymer")),
            stock: None,
            tolerance_mm: Some(0.2),
            quantity: Some(1),
            machines: None,
            constraints: Some(FabricationConstraints {
                max_setups: None,
                allow_human_intervention: Some(true),
                allow_multi_part_assembly: Some(false),
                require_dry_run: Some(true),
                preferred_methods: Some(vec!["fdm-3d-printing".to_string()]),
                preferred_assembly_strategy: None,
            }),
            parts: None,
            design_inputs: None,
            existing_instructions: None,
            learning: None,
        },
        Some(&policy),
    )
    .expect("slicer profile planning should succeed");

    let payload = slicer_profile_planning_response(&response, &policy);
    assert_eq!(
        payload.get("schemaVersion").and_then(Value::as_str),
        Some("dd.fabrication.slicer-profile-planning.v1")
    );
    assert!(payload
        .get("routes")
        .and_then(Value::as_array)
        .is_some_and(|routes| routes
            .iter()
            .any(|route| route.as_str() == Some("POST /fabrication/slicers/plan"))));
    assert!(payload
        .get("slicerProfileCatalog")
        .and_then(Value::as_array)
        .is_some_and(|profiles| profiles
            .iter()
            .any(|profile| profile.get("slicer").and_then(Value::as_str) == Some("OrcaSlicer"))));
    assert!(payload
        .get("slicerPlanning")
        .and_then(Value::as_array)
        .is_some_and(|plans| !plans.is_empty()
            && plans.iter().any(|plan| plan
                .get("profileEvidenceRequired")
                .and_then(Value::as_array)
                .is_some_and(|evidence| evidence.iter().any(|item| item
                    .as_str()
                    .is_some_and(|item| item.contains("support and orientation")))))));
    assert!(payload
        .get("additiveProgramCount")
        .and_then(Value::as_u64)
        .is_some_and(|count| count > 0));
    assert!(payload
        .get("generatedPrograms")
        .and_then(Value::as_array)
        .is_some_and(|programs| programs.iter().any(|program| program
            .get("instructions")
            .and_then(Value::as_array)
            .is_some_and(|instructions| !instructions.is_empty()))));
    assert_eq!(
        payload.get("machineReady").and_then(Value::as_bool),
        Some(false)
    );
    assert!(payload
        .get("responseSurfaces")
        .and_then(Value::as_array)
        .is_some_and(|surfaces| surfaces
            .iter()
            .any(|surface| { surface.as_str() == Some("generatedPrograms.instructions") })));
    assert!(payload
        .get("artifactSurfaces")
        .and_then(Value::as_array)
        .is_some_and(|surfaces| surfaces
            .iter()
            .any(|surface| { surface.as_str() == Some("mdp-request.artifacts.slicerPlan") })));
    assert!(payload
        .get("slicerProfilePolicy")
        .and_then(Value::as_array)
        .is_some_and(|policy| policy.iter().any(|item| item
            .as_str()
            .is_some_and(|item| item.contains("not certified print parameters")))));
}

#[test]
fn machine_code_result_endpoint_reviews_priority_dispositions() {
    let programs = vec![json!({
        "programId": "printer-job",
        "language": "marlin-printer-gcode",
        "status": "complete",
        "releaseEvidence": {
            "hasRetainedArtifact": true,
            "hasChecksum": true,
            "hasEvidence": true
        }
    })];
    let dispositions =
        machine_code_priority_dispositions(true, true, 0, 1, 1, true, false, &programs);

    assert!(dispositions.iter().any(|disposition| {
        disposition.get("priorityId").and_then(Value::as_str)
            == Some("machine-failure-boundary-first")
            && disposition.get("disposition").and_then(Value::as_str) == Some("blocked")
            && disposition
                .get("learningObservation")
                .and_then(Value::as_str)
                == Some("machine-code-priority:machine-failure-boundary-first:blocked")
    }));
    assert!(dispositions.iter().any(|disposition| {
        disposition.get("priorityId").and_then(Value::as_str) == Some("human-intervention-required")
            && disposition.get("disposition").and_then(Value::as_str) == Some("blocked")
    }));
    assert!(dispositions.iter().any(|disposition| {
        disposition.get("priorityId").and_then(Value::as_str)
            == Some("learning-feedback-after-disposition")
            && disposition.get("disposition").and_then(Value::as_str) == Some("ready-to-submit")
            && disposition
                .get("nextRoutes")
                .and_then(Value::as_array)
                .is_some_and(|routes| {
                    routes
                        .iter()
                        .any(|route| route.as_str() == Some("POST /fabrication/learning/outcomes"))
                })
    }));
}

#[test]
fn machine_code_result_endpoint_reviews_controller_checks_and_learning() {
    let payload = machine_code_result_review_response(MachineCodeResultReviewRequest {
        request_id: Some("unit-machine-code-result".to_string()),
        plan_request_id: Some("unit-machine-code-generate".to_string()),
        job_id: Some("machine-code-job-42".to_string()),
        worker_id: "postprocessor-worker-01".to_string(),
        generator: Some("haas-postprocessor".to_string()),
        generator_version: Some("3.7.1".to_string()),
        machine_id: Some("haas-vf2-01".to_string()),
        machine_kind: Some("vertical-mill".to_string()),
        controller: Some("haas-ngc".to_string()),
        postprocessor: Some("haas-mill-gcode-postprocessor".to_string()),
        success: true,
        machine_ready: false,
        release_ready: Some(false),
        programs: Some(vec![MachineCodeResultProgram {
            program_id: "finish-datum-pocket".to_string(),
            source_program_id: Some("program-finish-pocket-draft".to_string()),
            target_id: Some("datum-pocket".to_string()),
            operation_id: Some("op-finish-pocket".to_string()),
            language: "haas-gcode".to_string(),
            status: "complete".to_string(),
            output_format: Some("controller-gcode".to_string()),
            controller_dialect: Some("haas-ngc".to_string()),
            uri: Some("s3://fabrication/machine-code/finish-datum-pocket.nc".to_string()),
            sha256: Some("d".repeat(64)),
            estimated_runtime_sec: Some(412),
            release_blocker: Some(false),
            evidence: Some(vec![
                "postprocessed controller output retained with checksum".to_string(),
            ]),
            preview_lines: Some(vec!["G21 G90 G54".to_string(), "M6 T12".to_string()]),
        }]),
        controller_checks: Some(vec![MachineCodeResultControllerCheck {
            check_id: "controller-macro-review".to_string(),
            check_kind: "controller-macro-review".to_string(),
            status: "blocked".to_string(),
            controller: Some("haas-ngc".to_string()),
            postprocessor: Some("haas-mill-gcode-postprocessor".to_string()),
            machine_id: Some("haas-vf2-01".to_string()),
            release_blocker: Some(true),
            requires_human_intervention: Some(true),
            evidence: Some(vec![
                "subprogram O9001 and macro variables require operator review".to_string(),
            ]),
        }]),
        failure_boundaries: Some(vec![MachineCodeResultFailureBoundary {
            boundary_id: "macro-dependency-boundary".to_string(),
            boundary_kind: "controller-dependency-boundary".to_string(),
            code: "controller-dependency-not-verified".to_string(),
            message: "Controller macro package has not been verified against the live machine"
                .to_string(),
            program_id: Some("finish-datum-pocket".to_string()),
            segment_ref: Some("N120".to_string()),
            release_blocker: Some(true),
            requires_human_intervention: Some(true),
            recommended_action: Some("attach-macro-library-and-rerun-dry-run".to_string()),
            evidence: Some(vec!["controller macro library missing".to_string()]),
        }]),
        artifacts: Some(vec![MachineCodeResultArtifact {
            artifact_id: "machine-code-result-package".to_string(),
            artifact_kind: "machine-code-result-package".to_string(),
            program_id: Some("finish-datum-pocket".to_string()),
            uri: Some("s3://fabrication/machine-code/result-package.json".to_string()),
            sha256: Some("e".repeat(64)),
            format: Some("json".to_string()),
            evidence: Some(vec!["result package checksum retained".to_string()]),
        }]),
        warnings: Some(vec![
            "do not run until macro dependency review and dry-run pass".to_string(),
        ]),
        review_metadata: Some(json!({"source": "unit-test", "controllerRelease": false})),
    })
    .expect("machine-code result review should succeed");

    assert_eq!(
        payload.get("schemaVersion").and_then(Value::as_str),
        Some("dd.fabrication.machine-code-result-review.v1")
    );
    assert!(payload
        .get("routes")
        .and_then(Value::as_array)
        .is_some_and(|routes| routes
            .iter()
            .any(|route| route.as_str() == Some("POST /fabrication/machine-code/result"))));
    assert_eq!(
        payload.get("reviewStatus").and_then(Value::as_str),
        Some("machine-code-result-controller-checks-release-blocked")
    );
    assert_eq!(
        payload.get("releaseBlocked").and_then(Value::as_bool),
        Some(true)
    );
    assert_eq!(
        payload.get("machineReady").and_then(Value::as_bool),
        Some(false)
    );
    assert_eq!(
        payload.get("releaseReady").and_then(Value::as_bool),
        Some(false)
    );
    assert_eq!(payload.get("programCount").and_then(Value::as_u64), Some(1));
    assert_eq!(
        payload
            .get("controllerCheckBlockerCount")
            .and_then(Value::as_u64),
        Some(1)
    );
    assert_eq!(
        payload.get("boundaryBlockerCount").and_then(Value::as_u64),
        Some(1)
    );
    assert_eq!(
        payload
            .get("humanInterventionRequired")
            .and_then(Value::as_bool),
        Some(true)
    );
    assert_eq!(
        payload
            .get("missingProgramEvidenceCount")
            .and_then(Value::as_u64),
        Some(0)
    );
    assert_eq!(
        payload
            .get("missingArtifactEvidenceCount")
            .and_then(Value::as_u64),
        Some(0)
    );
    let priority_dispositions = payload
        .get("priorityDispositions")
        .and_then(Value::as_array)
        .expect("machine-code priority dispositions should be returned");
    assert!(priority_dispositions.iter().any(|disposition| {
        disposition.get("priorityId").and_then(Value::as_str)
            == Some("machine-failure-boundary-first")
            && disposition.get("disposition").and_then(Value::as_str) == Some("blocked")
            && disposition
                .get("nextRoutes")
                .and_then(Value::as_array)
                .is_some_and(|routes| {
                    routes
                        .iter()
                        .any(|route| route.as_str() == Some("POST /fabrication/simulation/run"))
                })
    }));
    assert!(priority_dispositions.iter().any(|disposition| {
        disposition.get("priorityId").and_then(Value::as_str) == Some("human-intervention-required")
            && disposition.get("disposition").and_then(Value::as_str) == Some("blocked")
    }));
    assert!(priority_dispositions.iter().any(|disposition| {
        disposition.get("priorityId").and_then(Value::as_str)
            == Some("learning-feedback-after-disposition")
            && disposition.get("disposition").and_then(Value::as_str) == Some("ready-to-submit")
    }));
    assert!(payload
        .get("machineCodeResult")
        .and_then(|result| result.get("controllerChecks"))
        .and_then(Value::as_array)
        .is_some_and(|checks| checks.iter().any(|check| {
            check.get("checkKind").and_then(Value::as_str) == Some("controller-macro-review")
        })));
    assert!(payload
        .get("artifactSurfaces")
        .and_then(Value::as_array)
        .is_some_and(|surfaces| surfaces.iter().any(|surface| {
            surface.as_str() == Some("mdp-request.artifacts.machineCodeResult")
        })));

    let observations = payload
        .get("learning")
        .and_then(|learning| learning.get("observations"))
        .and_then(Value::as_array)
        .expect("machine-code learning observations should be retained");
    for expected in [
        "machine-code-generator:haas-postprocessor",
        "machine-code-controller:haas-ngc",
        "machine-code-postprocessor:haas-mill-gcode-postprocessor",
        "machine-code-machine-kind:vertical-mill",
        "machine-code-program-language:haas-gcode",
        "machine-code-program-status:complete",
        "machine-code-check:controller-macro-review",
        "machine-code-check-status:blocked",
        "machine-code-boundary:controller-dependency-boundary",
        "machine-code-boundary-code:controller-dependency-not-verified",
        "machine-code-recommended-action:attach-macro-library-and-rerun-dry-run",
        "machine-code-artifact:machine-code-result-package",
        "machine-code:controller-check-blocked",
        "machine-code:boundary-blocked",
        "machine-code:human-intervention-required",
        "machine-code:release-blocked",
        "machine-code-priority:machine-failure-boundary-first:blocked",
    ] {
        assert!(
            observations
                .iter()
                .any(|observation| observation.as_str() == Some(expected)),
            "missing machine-code learning observation {expected}"
        );
    }
    let outcome_draft = payload
        .pointer("/learning/outcomeDraft")
        .expect("machine-code learning outcome draft");
    assert_eq!(
        outcome_draft.get("schemaVersion").and_then(Value::as_str),
        Some("dd.fabrication.machine-code-learning-outcome-draft.v1")
    );
    assert_eq!(
        outcome_draft
            .get("recommendedSubmitRoute")
            .and_then(Value::as_str),
        Some("POST /fabrication/learning/outcomes")
    );
    assert_eq!(
        outcome_draft.get("success").and_then(Value::as_bool),
        Some(false)
    );
    assert_eq!(
        outcome_draft.get("rewardHint").and_then(Value::as_f64),
        Some(-0.8)
    );
    assert_eq!(
        outcome_draft.get("controller").and_then(Value::as_str),
        Some("haas-ngc")
    );
    assert_eq!(
        outcome_draft.get("postprocessor").and_then(Value::as_str),
        Some("haas-mill-gcode-postprocessor")
    );
    assert!(outcome_draft
        .get("methodHints")
        .and_then(Value::as_array)
        .is_some_and(|hints| hints.iter().any(|hint| hint.as_str() == Some("haas-gcode"))));
    assert!(outcome_draft
        .get("boundaryHints")
        .and_then(Value::as_array)
        .is_some_and(|hints| hints
            .iter()
            .any(|hint| hint.as_str() == Some("controller-dependency-boundary"))));
    assert!(outcome_draft
        .get("featureHints")
        .and_then(Value::as_array)
        .is_some_and(|hints| hints
            .iter()
            .any(|hint| hint.as_str() == Some("controller-check-blockers:1"))));
    assert!(outcome_draft
        .get("featureHints")
        .and_then(Value::as_array)
        .is_some_and(|hints| hints
            .iter()
            .any(|hint| hint.as_str() == Some("priority-dispositions:4"))));
    assert!(outcome_draft
        .get("priorityDispositions")
        .and_then(Value::as_array)
        .is_some_and(|dispositions| dispositions.iter().any(|disposition| {
            disposition.get("priorityId").and_then(Value::as_str)
                == Some("human-intervention-required")
        })));
    assert!(outcome_draft
        .get("recommendedActions")
        .and_then(Value::as_array)
        .is_some_and(|actions| actions
            .iter()
            .any(|action| action.as_str() == Some("attach-macro-library-and-rerun-dry-run"))));

    let machine_code_result_job_id = payload
        .get("machineCodeResultJobId")
        .and_then(Value::as_str)
        .expect("machine-code result should expose a retained job id");
    assert!(machine_code_result_job_id.starts_with("machine-code-result-unit-machine-code-result-"));
    let job = stored_machine_code_result_job(&payload);
    assert_eq!(job.record.job_id, machine_code_result_job_id);
    assert_eq!(job.record.kind, "machine-code-result");
    assert_eq!(
        job.record.status,
        "machine-code-result-controller-checks-release-blocked"
    );
    assert_eq!(job.record.ok, false);
    assert_eq!(job.record.severity, "error");
    for artifact_id in [
        "machine-code-result",
        "machine-code-programs",
        "machine-code-controller-checks",
        "machine-code-failure-boundaries",
        "machine-code-artifacts",
        "machine-code-priority-dispositions",
        "machine-code-learning-observations",
    ] {
        assert!(
            job.artifacts.contains_key(artifact_id),
            "missing machine-code result artifact {artifact_id}"
        );
    }
}

