#[test]
fn release_catalog_endpoint_exposes_machine_ready_package_contract() {
    let payload = release_catalog_response();
    assert_eq!(
        payload.get("schemaVersion").and_then(Value::as_str),
        Some("dd.fabrication.release-catalog.v1")
    );
    assert!(payload
        .get("routes")
        .and_then(Value::as_array)
        .is_some_and(|routes| routes
            .iter()
            .any(|route| route.as_str() == Some("GET /fabrication/release/catalog"))));
    assert!(payload
        .get("gateCount")
        .and_then(Value::as_u64)
        .is_some_and(|count| count >= 5));
    assert!(payload
        .get("responseSurfaces")
        .and_then(Value::as_array)
        .is_some_and(|surfaces| surfaces
            .iter()
            .any(|surface| surface.as_str() == Some("machineRelease.blockers"))));
    assert!(payload
        .get("learningSurfaces")
        .and_then(Value::as_array)
        .is_some_and(|surfaces| surfaces.iter().any(|surface| {
            surface.as_str() == Some("releasePackagePlan.learningObservations")
        })));
    assert!(payload
        .get("releasePolicy")
        .and_then(Value::as_array)
        .is_some_and(|policy| policy.iter().any(|item| item
            .as_str()
            .is_some_and(|item| item.contains("machine-ready release remains blocked")))));

    let package_kinds = payload
        .get("packageKinds")
        .and_then(Value::as_array)
        .expect("release package kinds should be present");
    for package_kind in ["machine-program-release", "assembly-recomposition-release"] {
        assert!(
            package_kinds
                .iter()
                .any(|item| item.as_str() == Some(package_kind)),
            "missing package kind {package_kind}"
        );
    }

    let gate_contracts = payload
        .get("gateContracts")
        .and_then(Value::as_array)
        .expect("gate contracts should be present");
    for gate_type in [
        "machine-release-signoff",
        "controller-postprocess-compatibility",
        "split-combine-interface-release",
    ] {
        assert!(
            gate_contracts
                .iter()
                .any(|item| { item.get("gateType").and_then(Value::as_str) == Some(gate_type) }),
            "missing release gate {gate_type}"
        );
    }
    let split_combine_gate = gate_contracts
        .iter()
        .find(|item| {
            item.get("gateType").and_then(Value::as_str) == Some("split-combine-interface-release")
        })
        .expect("split/combine release gate should be present");
    assert!(split_combine_gate
        .get("evidence")
        .and_then(Value::as_array)
        .is_some_and(|evidence| evidence.iter().any(|item| item
            .as_str()
            .is_some_and(|item| item.contains("decomposition target IDs")))));

    let blocker_sources = payload
        .get("blockerSources")
        .and_then(Value::as_array)
        .expect("blocker sources should be present");
    assert!(blocker_sources
        .iter()
        .any(|item| { item.get("source").and_then(Value::as_str) == Some("release-probe") }));

    let required_artifacts = payload
        .get("requiredArtifacts")
        .and_then(Value::as_array)
        .expect("required artifacts should be present");
    for artifact in [
        "release-package-plan",
        "machine-release",
        "simulation-report",
    ] {
        assert!(
            required_artifacts
                .iter()
                .any(|item| item.as_str() == Some(artifact)),
            "missing required release artifact {artifact}"
        );
    }
}

#[test]
fn release_gate_catalog_endpoint_exposes_machine_ready_gate_matrix() {
    let payload = release_gate_catalog_response();
    assert_eq!(
        payload.get("schemaVersion").and_then(Value::as_str),
        Some("dd.fabrication.release-gate-catalog.v1")
    );
    assert!(payload
        .get("routes")
        .and_then(Value::as_array)
        .is_some_and(|routes| routes
            .iter()
            .any(|route| route.as_str() == Some("GET /fabrication/release/gates/catalog"))));
    assert_eq!(
        payload.get("gateCount").and_then(Value::as_u64),
        Some(release_catalog_gate_contracts().len() as u64)
    );
    assert!(payload
        .get("machineReadyRule")
        .and_then(Value::as_str)
        .is_some_and(|rule| rule.contains("machineReady remains false")));
    let gate_contracts = payload
        .get("gateContracts")
        .and_then(Value::as_array)
        .expect("release gate catalog should include gate contracts");
    for expected in [
        "design-export-review",
        "setup-quality-monitoring-evidence",
        "machine-release-signoff",
        "controller-postprocess-compatibility",
        "split-combine-interface-release",
    ] {
        assert!(
            gate_contracts
                .iter()
                .any(|gate| { gate.get("gateType").and_then(Value::as_str) == Some(expected) }),
            "missing release gate contract {expected}"
        );
    }
    let payload_text = payload.to_string();
    for expected in [
            "priorityDispositions",
            "releaseReadinessResult.learning.outcomeDraft",
            "generated designs, machine code, slicer jobs, imported CNC/controller streams, text job sheets, split routes, and recomposed assemblies remain advisory",
            "learned policy never bypasses release gates",
        ] {
            assert!(
                payload_text.contains(expected),
                "release gate catalog should include {expected}"
            );
        }
}

