#[test]
fn strategy_recommendation_endpoint_exposes_learned_hybrid_preview() {
    let policy = LearningPolicySnapshot {
        outcome_count: 2,
        successes: 2,
        failures: 0,
        average_reward: 2.4,
        method_preferences: Vec::new(),
        method_combination_preferences: vec![LearningPreference {
            key: "additive-print+milling".to_string(),
            samples: 2,
            successes: 2,
            failures: 0,
            average_reward: 2.4,
            recommendation: "prefer".to_string(),
        }],
        machine_kind_preferences: Vec::new(),
        operation_sequence_preferences: Vec::new(),
        assembly_preferences: Vec::new(),
        split_combine_preferences: Vec::new(),
        remediation_risks: Vec::new(),
        neural_training_examples: Vec::new(),
        boundary_learning_examples: Vec::new(),
    };
    let response = plan_fabrication_with_policy(
        FabricationPlanRequest {
            request_id: Some("unit-strategy-recommend".to_string()),
            objective: "PLA fixture body with milled datum pads".to_string(),
            material: Some(material("pla", "polymer")),
            stock: None,
            tolerance_mm: Some(0.12),
            quantity: Some(1),
            machines: None,
            constraints: None,
            parts: None,
            design_inputs: None,
            existing_instructions: None,
            learning: None,
        },
        Some(&policy),
    )
    .expect("learned strategy recommendation plan should succeed");

    let payload = strategy_recommendation_response(&response, &policy);
    assert_eq!(
        payload.get("schemaVersion").and_then(Value::as_str),
        Some("dd.fabrication.strategy-recommendation.v1")
    );
    assert!(payload
        .get("routes")
        .and_then(Value::as_array)
        .is_some_and(|routes| routes
            .iter()
            .any(|route| route.as_str() == Some("POST /fabrication/strategy/recommend"))));
    assert_eq!(
        payload
            .get("policySummary")
            .and_then(|summary| summary.get("methodCombinationPreferenceCount"))
            .and_then(Value::as_u64),
        Some(1)
    );
    assert_eq!(
        payload
            .get("policySummary")
            .and_then(|summary| summary.get("successRate"))
            .and_then(Value::as_f64),
        Some(1.0)
    );
    assert_eq!(
        payload
            .get("learningOutcomeQuality")
            .and_then(|quality| quality.get("releasePolicy"))
            .and_then(Value::as_str),
        Some("positive-learned-route-evidence")
    );
    assert_eq!(
        payload
            .get("learningOutcomeQuality")
            .and_then(|quality| quality.get("riskReviewRequired"))
            .and_then(Value::as_bool),
        Some(false)
    );
    assert!(payload
        .get("topStrategyCandidate")
        .is_some_and(|candidate| candidate.get("score").and_then(Value::as_f64).is_some()));
    assert!(payload
        .get("hybridMakePlan")
        .and_then(|plan| plan.get("partRoutes"))
        .and_then(Value::as_array)
        .is_some_and(|routes| !routes.is_empty()));
    assert!(
        payload
            .get("learning")
            .and_then(|learning| learning.get("engine"))
            .and_then(|engine| engine.get("crateName"))
            .and_then(Value::as_str)
            == Some("des_engine")
    );
    assert!(payload
        .get("recommendationPolicy")
        .and_then(Value::as_array)
        .is_some_and(|policy| policy
            .iter()
            .any(|item| item.as_str().is_some_and(|item| item.contains("advisory")))));
    assert_eq!(
        payload.get("machineReady").and_then(Value::as_bool),
        Some(false)
    );

    let risk_policy = LearningPolicySnapshot {
        outcome_count: 2,
        successes: 1,
        failures: 1,
        average_reward: -0.2,
        method_preferences: Vec::new(),
        method_combination_preferences: Vec::new(),
        machine_kind_preferences: Vec::new(),
        operation_sequence_preferences: Vec::new(),
        assembly_preferences: Vec::new(),
        split_combine_preferences: Vec::new(),
        remediation_risks: vec![LearningRemediationRisk {
            key: "milling@petg".to_string(),
            method: "milling".to_string(),
            material: Some("petg".to_string()),
            material_family: Some("polymer".to_string()),
            samples: 1,
            failures: 1,
            average_reward: -1.4,
            severity: "high".to_string(),
            review_action: "review-prior-failure-outcome-before-release".to_string(),
            observations: vec!["machine-failure:thin-wall-chatter".to_string()],
            recommended_actions: vec!["split-before-milling".to_string()],
            last_outcome_id: "risk-outcome-1".to_string(),
        }],
        neural_training_examples: Vec::new(),
        boundary_learning_examples: Vec::new(),
    };
    let risk_payload = strategy_recommendation_response(&response, &risk_policy);
    assert_eq!(
        risk_payload
            .get("learningOutcomeQuality")
            .and_then(|quality| quality.get("releasePolicy"))
            .and_then(Value::as_str),
        Some("review-learned-route-quality-before-release")
    );
    assert_eq!(
        risk_payload
            .get("learningOutcomeQuality")
            .and_then(|quality| quality.get("riskReviewRequired"))
            .and_then(Value::as_bool),
        Some(true)
    );
}

