#[test]
fn learning_feature_catalog_endpoint_exposes_feature_map_for_policy_workers() {
    let payload = learning_feature_catalog_response();
    assert_eq!(
        payload.get("schemaVersion").and_then(Value::as_str),
        Some("dd.fabrication.learning-feature-catalog.v1")
    );
    assert!(payload
        .get("routes")
        .and_then(Value::as_array)
        .is_some_and(|routes| routes.iter().any(|route| {
            route.as_str() == Some("GET /fabrication/learning/features/catalog")
        })));
    assert_eq!(
        payload
            .get("preferredPrimitiveSource")
            .and_then(|source| source.get("crate"))
            .and_then(Value::as_str),
        Some("des_engine")
    );
    let groups = payload
        .get("featureGroups")
        .and_then(Value::as_array)
        .expect("learning feature groups should be exposed");
    for group in [
        "plan-route-and-material-state",
        "instruction-validation-boundary-state",
        "split-combine-interface-state",
        "release-evidence-and-outcome-state",
        "neural-policy-input-vector",
    ] {
        assert!(
            groups
                .iter()
                .any(|item| item.get("group").and_then(Value::as_str) == Some(group)),
            "missing learning feature group {group}"
        );
    }
    assert!(groups.iter().any(
        |item| item
            .get("features")
            .and_then(Value::as_array)
            .is_some_and(|features| features
                .iter()
                .any(|feature| feature.as_str() == Some("toolpath-token-sequence")))
    ));
    assert!(groups.iter().any(
        |item| item
            .get("surfaces")
            .and_then(Value::as_array)
            .is_some_and(|surfaces| surfaces.iter().any(|surface| {
                surface.as_str() == Some("hybridMakePlan.splitCombineDecisions")
            }))
    ));
    let hybrid_decisions = payload
        .get("hybridDecisionFeatureContracts")
        .and_then(Value::as_array)
        .expect("hybrid decision feature contracts should be exposed");
    assert_eq!(hybrid_decisions.len(), 3);
    for decision in [
        "attempt-single-piece-fabrication",
        "split-print-mill-or-turn",
        "recompose-and-release-interfaces",
    ] {
        assert!(
            hybrid_decisions
                .iter()
                .any(|item| item.get("decision").and_then(Value::as_str) == Some(decision)),
            "missing hybrid decision feature contract {decision}"
        );
    }
    let hybrid_decision_text =
        serde_json::to_string(hybrid_decisions).expect("hybrid decisions should serialize");
    for expected in [
        "split-for-printing",
        "split-for-milling",
        "split-for-turning",
        "interfaceControlPlan.controls",
        "machineReady remains false",
        "combined parts cannot become machine-ready",
    ] {
        assert!(
            hybrid_decision_text.contains(expected),
            "hybrid decision contracts should include {expected}"
        );
    }
    assert!(payload
        .get("normalizationPolicy")
        .and_then(Value::as_array)
        .is_some_and(|policy| policy.iter().any(|item| item
            .as_str()
            .is_some_and(|item| item.contains("advisory until validation")))));
}

