#[test]
fn subtractive_analysis_requires_process_shutdown_before_program_end() {
    let programs = vec![
            program(
                "active-process-at-end",
                "vertical-mill",
                &[
                    "G21 G90 G54 ; ATC magazine, vise clamps, stock stop, datum probed, and chip-load evidence verified",
                    "T1 M6 ; ATC magazine verified",
                    "G43 H1 ; tool length probe verified",
                    "S8000 M3",
                    "M8 ; coolant active",
                    "G0 X0 Y0 Z12",
                    "G1 Z-1.0 F120",
                    "G1 X25.0 F260",
                    "M30",
                ],
            ),
            program(
                "stopped-process-at-end",
                "vertical-mill",
                &[
                    "G21 G90 G54 ; ATC magazine, vise clamps, stock stop, datum probed, and chip-load evidence verified",
                    "T1 M6 ; ATC magazine verified",
                    "G43 H1 ; tool length probe verified",
                    "S8000 M3",
                    "M8 ; coolant active",
                    "G0 X0 Y0 Z12",
                    "G1 Z-1.0 F120",
                    "G1 X25.0 F260",
                    "M5 ; spindle stopped and verified",
                    "M9 ; coolant off and chip conveyor stopped",
                    "M30",
                ],
            ),
        ];

    let (_, validation, improvements) = analyze_instruction_programs(&programs);

    assert_eq!(validation.severity, "warning");
    assert!(validation.findings.iter().any(|finding| {
        finding.code == "process-not-stopped-before-program-end"
            && finding.program_id.as_deref() == Some("active-process-at-end")
            && finding.line == Some(9)
    }));
    assert!(validation.failure_boundaries.iter().any(|boundary| {
        boundary.kind == "machine-process-end-boundary"
            && boundary.program_id.as_deref() == Some("active-process-at-end")
            && boundary.line == Some(9)
            && boundary.requires_human_intervention
            && boundary.suggested_resolution.contains("M5/M05")
    }));
    assert!(validation.findings.iter().any(|finding| {
        finding.code == "process-media-not-stopped-before-program-end"
            && finding.program_id.as_deref() == Some("active-process-at-end")
            && finding.line == Some(9)
    }));
    assert!(validation.failure_boundaries.iter().any(|boundary| {
        boundary.kind == "process-media-end-boundary"
            && boundary.program_id.as_deref() == Some("active-process-at-end")
            && boundary.line == Some(9)
            && boundary.requires_human_intervention
            && boundary.suggested_resolution.contains("M9/M09")
    }));
    assert!(!validation.findings.iter().any(|finding| {
        (finding.code == "process-not-stopped-before-program-end"
            || finding.code == "process-media-not-stopped-before-program-end")
            && finding.program_id.as_deref() == Some("stopped-process-at-end")
    }));
    assert!(improvements.is_empty());

    let improved = improve_instruction_programs(&programs, &validation, &improvements);
    assert!(!improved[0].changed);
    assert!(!improved[1].changed);
}

#[test]
fn lathe_analysis_flags_css_threading_and_partoff_boundaries() {
    let programs = vec![program(
        "risky-lathe",
        "lathe",
        &[
            "G21 G90 G54",
            "T0303",
            "G96 S220 M3",
            "G1 X18 Z-20 F0.18",
            "G76 X16 Z-30 P010060 Q100 F1.5",
            "G1 X2 Z-35 F0.04 ; part-off cutoff",
            "M30",
        ],
    )];

    let (analyzed, validation, improvements) = analyze_instruction_programs(&programs);

    assert_eq!(analyzed[0].machine_kind, "lathe");
    assert_eq!(validation.severity, "warning");
    assert!(validation
        .findings
        .iter()
        .any(|finding| finding.code == "lathe-css-without-spindle-limit"));
    assert!(validation
        .findings
        .iter()
        .any(|finding| finding.code == "lathe-threading-boundary"));
    assert!(validation
        .findings
        .iter()
        .any(|finding| finding.code == "lathe-part-off-boundary"));
    assert!(validation.failure_boundaries.iter().any(|boundary| {
        boundary.kind == "lathe-spindle-speed-boundary" && boundary.requires_human_intervention
    }));
    assert!(validation
        .failure_boundaries
        .iter()
        .any(|boundary| boundary.kind == "lathe-threading-boundary"));
    assert!(validation
        .failure_boundaries
        .iter()
        .any(|boundary| boundary.kind == "lathe-part-off-boundary"));
    assert!(improvements.is_empty());

    let improved = improve_instruction_programs(&programs, &validation, &improvements);
    assert!(improved[0].changed);
    assert!(improved[0]
        .instructions
        .iter()
        .any(|line| line.contains("boundary lathe-spindle-speed-boundary")));
    assert!(improved[0]
        .instructions
        .iter()
        .any(|line| line.contains("boundary lathe-threading-boundary")));
    assert!(improved[0]
        .instructions
        .iter()
        .any(|line| line.contains("boundary lathe-part-off-boundary")));
}

