#[test]
fn fabrication_outcome_enriches_learning_from_source_plan_job() {
    let plan = plan_fabrication(FabricationPlanRequest {
        request_id: Some("unit-source-context-plan".to_string()),
        objective: "PLA fixture with a printed body and milled datum pad".to_string(),
        material: Some(material("pla", "polymer")),
        stock: None,
        tolerance_mm: Some(0.12),
        quantity: Some(1),
        machines: Some(vec![
            MachineProfile {
                id: "fixture-printer".to_string(),
                kind: "fdm-printer".to_string(),
                controller: Some("marlin".to_string()),
                materials: Some(vec!["pla".to_string()]),
                work_envelope_mm: Some(vec![220.0, 220.0, 220.0]),
                axes: Some(3),
                operations: Some(vec!["additive-print".to_string()]),
                profile_evidence: None,
            },
            MachineProfile {
                id: "fixture-mill".to_string(),
                kind: "vertical-mill".to_string(),
                controller: Some("haas-gcode".to_string()),
                materials: Some(vec!["pla".to_string()]),
                work_envelope_mm: Some(vec![300.0, 180.0, 120.0]),
                axes: Some(3),
                operations: Some(vec!["face".to_string(), "contour".to_string()]),
                profile_evidence: None,
            },
        ]),
        constraints: None,
        parts: Some(vec![
            RequestedPart {
                id: "printed-body".to_string(),
                description: "printed fixture body".to_string(),
                material: Some(material("pla", "polymer")),
                preferred_method: Some("additive-print".to_string()),
                tolerance_mm: Some(0.18),
            },
            RequestedPart {
                id: "milled-datum-pad".to_string(),
                description: "datum pad machined after printing".to_string(),
                material: Some(material("pla", "polymer")),
                preferred_method: Some("milling".to_string()),
                tolerance_mm: Some(0.08),
            },
        ]),
        design_inputs: None,
        existing_instructions: None,
        learning: None,
    })
    .expect("source fabrication plan should succeed");
    let mill_program = plan
        .generated_programs
        .iter()
        .find(|program| program.machine_kind == "vertical-mill")
        .expect("plan should generate a vertical mill program");
    let source_artifact_id = artifact_id("program", &mill_program.program_id);
    let mut store = FabricationJobStore::new(4);
    assert!(
        store.insert(stored_plan_job(&plan)).is_none(),
        "first store of a job id cannot displace anything"
    );
    let stored_job = store
        .get(&plan.job_id)
        .expect("source plan job should be retrievable for enrichment");

    let sparse_outcome = FabricationOutcomeRequest {
        request_id: Some("unit-source-context-outcome".to_string()),
        source_job_id: Some(plan.job_id.clone()),
        source_artifact_id: Some(source_artifact_id.clone()),
        part_id: None,
        program_id: None,
        machine_id: None,
        machine_kind: None,
        operation_sequence: None,
        material: None,
        outcome: "hybrid fixture completed and datum inspection passed".to_string(),
        completed: Some(true),
        machine_failure: Some(false),
        scrap: Some(false),
        human_intervention_required: Some(false),
        intervention_minutes: Some(0.0),
        duration_minutes: Some(38.0),
        dimensional_error_mm: Some(0.05),
        surface_quality: Some(0.88),
        observations: None,
        notes: None,
        reward_weights: None,
    };
    let enriched = enrich_outcome_with_stored_job_context(sparse_outcome, &stored_job);
    let (response, record) =
        learn_from_outcome(enriched).expect("enriched sparse outcome should learn");

    assert!(response.ok);
    assert_eq!(
        response.source_job_id.as_deref(),
        Some(plan.job_id.as_str())
    );
    assert_eq!(
        response.source_artifact_id.as_deref(),
        Some(source_artifact_id.as_str())
    );
    assert_eq!(record.job_id.as_deref(), Some(plan.job_id.as_str()));
    assert_eq!(
        record.material.as_ref().map(|value| value.name.as_str()),
        Some("pla")
    );
    assert_eq!(record.machine_kind.as_deref(), Some("vertical-mill"));
    assert!(record
        .operation_sequence
        .iter()
        .any(|operation| operation.contains("additive-print")));
    assert!(record
        .operation_sequence
        .iter()
        .any(|operation| operation.contains("mill")));
    assert!(record
        .manufacturing_methods
        .iter()
        .any(|method| method == "additive-print"));
    assert!(record
        .manufacturing_methods
        .iter()
        .any(|method| method == "milling"));
    assert!(response
        .observations
        .iter()
        .any(|observation| observation == "source-plan-job:fabrication-plan"));
    assert!(response
        .observations
        .iter()
        .any(|observation| observation == "source-plan-method:additive-print"));
    assert!(response
        .observations
        .iter()
        .any(|observation| observation == "source-plan-method:milling"));
    assert!(response
        .observations
        .iter()
        .any(|observation| observation.starts_with("source-plan-program:")));
    assert!(response
        .neural_example
        .get("features")
        .and_then(|features| features.get("manufacturingMethods"))
        .and_then(Value::as_array)
        .is_some_and(|methods| methods
            .iter()
            .any(|method| method.as_str() == Some("milling"))));

    let mut memory = LearningMemory::new(8);
    memory.insert(record);
    let snapshot = memory.snapshot();
    assert!(snapshot
        .method_combination_preferences
        .iter()
        .any(|preference| preference.key == "additive-print+milling"));
    assert!(snapshot
        .machine_kind_preferences
        .iter()
        .any(|preference| preference.key == "vertical-mill"));
}

#[test]
fn fabrication_outcome_creates_reward_and_training_artifacts() {
    let (response, record) = learn_from_outcome(FabricationOutcomeRequest {
        request_id: Some("unit-outcome".to_string()),
        source_job_id: Some("plan-unit-artifact-plan-123".to_string()),
        source_artifact_id: Some("program-main".to_string()),
        part_id: Some("bracket".to_string()),
        program_id: Some("mill-bracket".to_string()),
        machine_id: Some("vertical-mill-1".to_string()),
        machine_kind: Some("vertical-mill".to_string()),
        operation_sequence: None,
        material: Some(material("aluminum", "metal")),
        outcome: "machine alarm; part scrapped after manual intervention".to_string(),
        completed: Some(false),
        machine_failure: Some(true),
        scrap: Some(true),
        human_intervention_required: Some(true),
        intervention_minutes: Some(18.0),
        duration_minutes: Some(42.0),
        dimensional_error_mm: Some(0.42),
        surface_quality: Some(0.25),
        observations: Some(vec!["spindle load spike".to_string()]),
        notes: Some(vec!["revise feeds and split the finish pass".to_string()]),
        reward_weights: None,
    })
    .expect("fabrication outcome should produce learning evidence");

    assert!(!response.ok);
    assert_eq!(response.state, "failed");
    assert_eq!(
        response.recommended_action,
        "reject-or-repostprocess-program"
    );
    assert!(response.reward < 0.0);
    assert!(response
        .observations
        .iter()
        .any(|observation| observation == "machine-failure"));
    assert_eq!(
        response.outcome_remediation.schema_version,
        "dd.fabrication.outcome-remediation.v1"
    );
    assert_eq!(
        response.outcome_remediation.status,
        "blocked-remediation-required"
    );
    assert!(response.outcome_remediation.human_review_required);
    assert!(response
        .outcome_remediation
        .root_causes
        .iter()
        .any(|cause| cause.category == "machine-failure-boundary"
            && cause.affected_program_id.as_deref() == Some("mill-bracket")));
    assert!(response
        .outcome_remediation
        .actions
        .iter()
        .any(|action| action.phase == "machine-release"
            && action.target_state == "failed-until-resolved"));
    assert!(response
        .outcome_remediation
        .learning_signals
        .iter()
        .any(|signal| signal.starts_with("outcome-root-cause:")));
    assert_eq!(
        response
            .mdp_update
            .get("schemaVersion")
            .and_then(Value::as_str),
        Some("dd.fabrication.learning-experience.v1")
    );
    assert!(response
        .mdp_update
        .get("outcomeRemediation")
        .and_then(|plan| plan.get("actions"))
        .and_then(Value::as_array)
        .is_some_and(|actions| !actions.is_empty()));
    assert_eq!(
        response
            .neural_example
            .get("schemaVersion")
            .and_then(Value::as_str),
        Some("dd.fabrication.neural-example.v1")
    );
    assert!(response
        .neural_example
        .get("features")
        .and_then(|features| features.get("outcomeRemediationSignals"))
        .and_then(Value::as_array)
        .is_some_and(|signals| !signals.is_empty()));

    let job = stored_learning_job(&response);
    assert_eq!(job.record.kind, "fabrication-learning-outcome");
    assert!(job.artifacts.contains_key("outcome-learning-event"));
    assert!(job.artifacts.contains_key("reward-signal"));
    assert!(job.artifacts.contains_key("mdp-experience"));
    assert!(job.artifacts.contains_key("outcome-remediation-plan"));
    assert!(job.artifacts.contains_key("pomdp-observations"));
    assert!(job.artifacts.contains_key("neural-example"));
    let remediation = job
        .artifacts
        .get("outcome-remediation-plan")
        .expect("outcome remediation artifact should be retained");
    assert_eq!(
        remediation
            .content
            .get("schemaVersion")
            .and_then(Value::as_str),
        Some("dd.fabrication.outcome-remediation.v1")
    );
    assert!(remediation
        .content
        .get("rootCauses")
        .and_then(Value::as_array)
        .is_some_and(|causes| !causes.is_empty()));

    let mut memory = LearningMemory::new(8);
    memory.insert(record);
    let snapshot = memory.snapshot();
    assert_eq!(snapshot.outcome_count, 1);
    assert_eq!(snapshot.failures, 1);
    assert!(snapshot.average_reward < 0.0);
    assert!(snapshot
        .method_preferences
        .iter()
        .any(|preference| preference.key == "milling"));
}

#[test]
fn learning_outcome_record_accepts_result_outcome_draft_payloads() {
    let request: LearningOutcomeRequest = serde_json::from_value(json!({
        "schemaVersion": "dd.fabrication.design-synthesis-learning-outcome-draft.v1",
        "sourceKind": "design-synthesis-result",
        "sourceJobId": "design-job-789",
        "sourceRequestId": "unit-design-synthesis-result",
        "success": true,
        "rewardHint": 0.5,
        "manufacturingMethodHints": ["milling", "turning", "additive-print"],
        "operationHints": ["additive-print", "milling", "turning"],
        "partHints": ["bracket-body", "turned-pin"],
        "featureHints": {
            "acceptedCandidateSelected": true,
            "candidateCount": 1,
            "releaseBlocked": false
        }
    }))
    .expect("outcome draft should deserialize as a learning outcome request");

    let record =
        learning_outcome_record(request).expect("outcome draft should convert to learning record");

    assert_eq!(record.request_id, "unit-design-synthesis-result");
    assert_eq!(record.job_id.as_deref(), Some("design-job-789"));
    assert_eq!(
        record.objective.as_deref(),
        Some("design-synthesis-result outcome")
    );
    assert_eq!(record.reward, 0.5);
    assert_eq!(
        record.operation_sequence,
        vec!["additive-print", "milling", "turning"]
    );
    assert!(record
        .manufacturing_methods
        .iter()
        .any(|method| method == "additive-print"));
    assert!(record
        .observations
        .iter()
        .any(|observation| observation == "source-kind:design-synthesis-result"));
    assert!(record
        .observations
        .iter()
        .any(|observation| observation == "hint:part:turned-pin"));
    assert!(record
        .observations
        .iter()
        .any(|observation| { observation == "hint:feature:accepted-candidate-selected:true" }));
}

#[test]
fn learning_outcomes_memory_endpoint_exposes_bounded_records_and_policy_snapshot() {
    let first_success = learning_outcome_record(LearningOutcomeRequest {
        request_id: Some("memory-success-1".to_string()),
        job_id: Some("plan-memory-1".to_string()),
        objective: Some("printed jig with milled datum".to_string()),
        material: Some(material("petg", "polymer")),
        manufacturing_methods: Some(vec!["additive-print".to_string(), "milling".to_string()]),
        machine_kind: Some("vertical-mill".to_string()),
        operation_sequence: Some(vec!["additive-print".to_string(), "milling".to_string()]),
        assembly_strategy: Some("printed body plus milled datum face".to_string()),
        source_kind: None,
        success: true,
        reward: Some(2.5),
        observations: Some(vec!["datum inspection passed".to_string()]),
        notes: Some(vec!["keep hybrid route".to_string()]),
        extra: BTreeMap::new(),
    })
    .expect("first memory outcome should be valid");
    let second_success = learning_outcome_record(LearningOutcomeRequest {
        request_id: Some("memory-success-2".to_string()),
        job_id: Some("plan-memory-2".to_string()),
        objective: Some("printed bracket with milled bearing pad".to_string()),
        material: Some(material("petg", "polymer")),
        manufacturing_methods: Some(vec!["additive-print".to_string(), "milling".to_string()]),
        machine_kind: Some("vertical-mill".to_string()),
        operation_sequence: Some(vec!["additive-print".to_string(), "milling".to_string()]),
        assembly_strategy: Some("printed body plus milled datum face".to_string()),
        source_kind: None,
        success: true,
        reward: Some(3.0),
        observations: Some(vec!["bearing pad passed".to_string()]),
        notes: Some(vec!["reuse datum allowance".to_string()]),
        extra: BTreeMap::new(),
    })
    .expect("second memory outcome should be valid");
    let failed_route = learning_outcome_record(LearningOutcomeRequest {
        request_id: Some("memory-failure-1".to_string()),
        job_id: Some("plan-memory-3".to_string()),
        objective: Some("single-piece milled PETG jig".to_string()),
        material: Some(material("petg", "polymer")),
        manufacturing_methods: Some(vec!["milling".to_string()]),
        machine_kind: Some("vertical-mill".to_string()),
        operation_sequence: Some(vec!["milling".to_string()]),
        assembly_strategy: Some("single-piece machining".to_string()),
        source_kind: None,
        success: false,
        reward: Some(-2.0),
        observations: Some(vec![
            "machine-failure:thin-wall-chatter".to_string(),
            "human-intervention-required".to_string(),
            "resolution-action:split-job-or-part".to_string(),
        ]),
        notes: Some(vec![
            "manual recovery required".to_string(),
            "prefer printed blank before milling".to_string(),
        ]),
        extra: BTreeMap::new(),
    })
    .expect("failed memory outcome should be valid");

    let mut memory = LearningMemory::new(2);
    memory.insert(first_success);
    memory.insert(second_success);
    memory.insert(failed_route);
    let payload = learning_outcomes_memory_response(&memory);

    assert_eq!(
        payload.get("schemaVersion").and_then(Value::as_str),
        Some("dd.fabrication.learning-outcome-memory.v1")
    );
    assert_eq!(payload.get("outcomeCount").and_then(Value::as_u64), Some(2));
    assert_eq!(payload.get("maxOutcomes").and_then(Value::as_u64), Some(2));
    assert!(payload
        .get("routes")
        .and_then(Value::as_array)
        .is_some_and(|routes| routes
            .iter()
            .any(|route| route.as_str() == Some("GET /fabrication/learning/outcomes"))));
    let outcomes = payload
        .get("outcomes")
        .and_then(Value::as_array)
        .expect("bounded outcomes should be present");
    assert!(!outcomes.iter().any(
        |outcome| outcome.get("requestId").and_then(Value::as_str) == Some("memory-success-1")
    ));
    assert!(outcomes.iter().any(
        |outcome| outcome.get("requestId").and_then(Value::as_str) == Some("memory-success-2")
    ));
    assert!(outcomes.iter().any(
        |outcome| outcome.get("requestId").and_then(Value::as_str) == Some("memory-failure-1")
    ));
    assert_eq!(
        payload
            .get("policy")
            .and_then(|policy| policy.get("outcomeCount"))
            .and_then(Value::as_u64),
        Some(2)
    );
    assert!(payload
        .get("policy")
        .and_then(|policy| policy.get("methodCombinationPreferences"))
        .and_then(Value::as_array)
        .is_some_and(|preferences| preferences
            .iter()
            .any(|preference| preference.get("key").and_then(Value::as_str)
                == Some("additive-print+milling"))));
    assert!(payload
        .get("policy")
        .and_then(|policy| policy.get("splitCombinePreferences"))
        .and_then(Value::as_array)
        .is_some_and(|preferences| preferences.iter().any(|preference| preference
            .get("key")
            .and_then(Value::as_str)
            .is_some_and(|key| key.contains("split") || key.contains("hybrid")))));
    assert!(payload
        .get("policy")
        .and_then(|policy| policy.get("remediationRisks"))
        .and_then(Value::as_array)
        .is_some_and(|risks| risks
            .iter()
            .any(|risk| risk.get("method").and_then(Value::as_str) == Some("milling"))));
    assert_eq!(
        payload
            .pointer("/qualitySummary/successCount")
            .and_then(Value::as_u64),
        Some(1)
    );
    assert_eq!(
        payload
            .pointer("/qualitySummary/failureCount")
            .and_then(Value::as_u64),
        Some(1)
    );
    assert_eq!(
        payload
            .pointer("/qualitySummary/positiveRewardCount")
            .and_then(Value::as_u64),
        Some(1)
    );
    assert_eq!(
        payload
            .pointer("/qualitySummary/negativeRewardCount")
            .and_then(Value::as_u64),
        Some(1)
    );
    assert_eq!(
        payload
            .pointer("/qualitySummary/hybridOutcomeCount")
            .and_then(Value::as_u64),
        Some(1)
    );
    assert_eq!(
        payload
            .pointer("/qualitySummary/interventionHeavyCount")
            .and_then(Value::as_u64),
        Some(1)
    );
    assert!(payload
        .get("qualityBuckets")
        .and_then(Value::as_array)
        .is_some_and(|buckets| buckets.iter().any(|bucket| bucket
            .get("bucket")
            .and_then(Value::as_str)
            == Some("failed-or-negative-reward")
            && bucket
                .get("policyUse")
                .and_then(Value::as_str)
                .is_some_and(|policy| policy.contains("release-probe evidence")))));
    assert!(payload
        .get("qualityBuckets")
        .and_then(Value::as_array)
        .is_some_and(|buckets| buckets.iter().any(|bucket| bucket
            .get("bucket")
            .and_then(Value::as_str)
            == Some("intervention-heavy")
            && bucket
                .get("policyUse")
                .and_then(Value::as_str)
                .is_some_and(|policy| policy.contains("POMDP hidden-state evidence")))));
    let policy_impact = payload
        .get("policyImpactPreview")
        .and_then(Value::as_array)
        .expect("policy impact preview should be exposed");
    for surface in [
        "methodCombinationPreferences",
        "machineKindPreferences",
        "operationSequencePreferences",
        "splitCombinePreferences",
        "remediationRisks",
        "neuralTrainingExamples",
    ] {
        assert!(
            policy_impact
                .iter()
                .any(|item| item.get("surface").and_then(Value::as_str) == Some(surface)),
            "policy impact preview should include {surface}"
        );
    }
    assert!(policy_impact.iter().any(|item| item
        .get("futureUse")
        .and_then(Value::as_str)
        .is_some_and(|future_use| future_use.contains("machine-ready release gated"))));
    assert!(policy_impact.iter().any(|item| item
        .get("futureUse")
        .and_then(Value::as_str)
        .is_some_and(|future_use| future_use
            .contains("without bypassing controller, setup, quality, or signoff"))));
}

#[test]
fn learning_policy_endpoint_exposes_self_describing_policy_snapshot() {
    let successful_hybrid = learning_outcome_record(LearningOutcomeRequest {
        request_id: Some("policy-success-1".to_string()),
        job_id: Some("plan-policy-1".to_string()),
        objective: Some("printed housing with milled precision pad".to_string()),
        material: Some(material("petg", "polymer")),
        manufacturing_methods: Some(vec!["additive-print".to_string(), "milling".to_string()]),
        machine_kind: Some("vertical-mill".to_string()),
        operation_sequence: Some(vec!["additive-print".to_string(), "milling".to_string()]),
        assembly_strategy: Some("printed body plus milled datum face".to_string()),
        source_kind: None,
        success: true,
        reward: Some(2.8),
        observations: Some(vec!["boundary-kind:split-combine-cleared".to_string()]),
        notes: Some(vec!["reuse hybrid route".to_string()]),
        extra: BTreeMap::new(),
    })
    .expect("successful hybrid outcome should be valid");
    let failed_single_route = learning_outcome_record(LearningOutcomeRequest {
        request_id: Some("policy-failure-1".to_string()),
        job_id: Some("plan-policy-2".to_string()),
        objective: Some("single-piece milled polymer housing".to_string()),
        material: Some(material("petg", "polymer")),
        manufacturing_methods: Some(vec!["milling".to_string()]),
        machine_kind: Some("vertical-mill".to_string()),
        operation_sequence: Some(vec!["milling".to_string()]),
        assembly_strategy: Some("single-piece machining".to_string()),
        source_kind: None,
        success: false,
        reward: Some(-2.4),
        observations: Some(vec!["machine-failure:thin-wall-chatter".to_string()]),
        notes: Some(vec!["split before retry".to_string()]),
        extra: BTreeMap::new(),
    })
    .expect("failed single-route outcome should be valid");

    let mut memory = LearningMemory::new(8);
    memory.insert(successful_hybrid);
    memory.insert(failed_single_route);
    let snapshot = memory.snapshot();
    let payload = learning_policy_response(&snapshot);

    assert_eq!(
        payload.get("schemaVersion").and_then(Value::as_str),
        Some("dd.fabrication.learning-policy-snapshot.v1")
    );
    assert!(payload
        .get("routes")
        .and_then(Value::as_array)
        .is_some_and(|routes| routes
            .iter()
            .any(|route| route.as_str() == Some("GET /fabrication/learning/policy"))));
    assert_eq!(
        payload
            .get("engine")
            .and_then(|engine| engine.get("crateName"))
            .and_then(Value::as_str),
        Some("des_engine")
    );
    assert_eq!(
        payload
            .get("engine")
            .and_then(|engine| engine.get("sourceCrate"))
            .and_then(Value::as_str),
        Some("remote/submodules/discrete-event-system.rs")
    );
    assert_eq!(
        payload
            .get("policySummary")
            .and_then(|summary| summary.get("outcomeCount"))
            .and_then(Value::as_u64),
        Some(2)
    );
    assert!(payload
        .get("policySummary")
        .and_then(|summary| summary.get("remediationRiskCount"))
        .and_then(Value::as_u64)
        .is_some_and(|count| count >= 1));
    assert!(payload
        .get("responseSurfaces")
        .and_then(Value::as_array)
        .is_some_and(|surfaces| surfaces
            .iter()
            .any(|surface| { surface.as_str() == Some("policy.methodCombinationPreferences") })));
    assert!(payload
        .get("responseSurfaces")
        .and_then(Value::as_array)
        .is_some_and(|surfaces| surfaces
            .iter()
            .any(|surface| surface.as_str() == Some("policy.splitCombinePreferences"))));
    assert!(payload
        .pointer("/policySummary/splitCombinePreferenceCount")
        .and_then(Value::as_u64)
        .is_some_and(|count| count >= 1));
    assert!(payload
        .get("promotionPolicy")
        .and_then(Value::as_array)
        .is_some_and(|policy| policy.iter().any(|note| note
            .as_str()
            .is_some_and(|note| note.contains("not certified machine-release authority")))));
    assert!(payload
        .get("policy")
        .and_then(|policy| policy.get("boundaryLearningExamples"))
        .and_then(Value::as_array)
        .is_some_and(|examples| !examples.is_empty()));
}

